import { createAPIFileRoute } from '@tanstack/react-start/api'
import { castVote } from '../../../db'
import { v4 as uuidv4 } from 'uuid'

function getCookie(request: Request, name: string): string | null {
  const cookieHeader = request.headers.get('Cookie') || ''
  const cookies = cookieHeader.split(';').map(c => c.trim())
  for (const cookie of cookies) {
    const [k, v] = cookie.split('=')
    if (k === name) return decodeURIComponent(v || '')
  }
  return null
}

export const Route = createAPIFileRoute('/api/polls/$id/vote')({
  POST: async ({ request, params }) => {
    const { id: pollId } = params
    try {
      const body = await request.json()
      const { optionId } = body as { optionId?: string }

      if (!optionId) {
        return new Response(JSON.stringify({ error: 'optionId is required' }), {
          status: 400,
          headers: { 'Content-Type': 'application/json' },
        })
      }

      let clientId = getCookie(request, 'client_id')
      let setCookieHeader: string | null = null

      if (!clientId) {
        clientId = uuidv4()
        setCookieHeader = `client_id=${clientId}; Path=/; Max-Age=31536000; HttpOnly; SameSite=Lax`
      }

      try {
        const updatedPoll = await castVote(pollId, optionId, clientId)

        const headers: Record<string, string> = {
          'Content-Type': 'application/json',
        }
        if (setCookieHeader) {
          headers['Set-Cookie'] = setCookieHeader
        } else {
          // Send it anyway to refresh/make sure they have it
          headers['Set-Cookie'] = `client_id=${clientId}; Path=/; Max-Age=31536000; HttpOnly; SameSite=Lax`
        }

        return new Response(JSON.stringify(updatedPoll), {
          status: 200,
          headers,
        })
      } catch (err: any) {
        if (err.message === 'POLL_NOT_FOUND' || err.message === 'OPTION_NOT_FOUND') {
          return new Response(JSON.stringify({ error: 'Poll or option not found' }), {
            status: 404,
            headers: { 'Content-Type': 'application/json' },
          })
        }
        if (err.message === 'ALREADY_VOTED') {
          return new Response(JSON.stringify({ error: 'You have already voted on this poll' }), {
            status: 409,
            headers: { 'Content-Type': 'application/json' },
          })
        }
        throw err
      }
    } catch (err: any) {
      return new Response(JSON.stringify({ error: err.message }), {
        status: 500,
        headers: { 'Content-Type': 'application/json' },
      })
    }
  }
})

import { createFileRoute, Link, useNavigate } from '@tanstack/react-router'
import { createServerFn } from '@tanstack/react-start'
import { useState } from 'react'
import { listPolls } from '../db'

const getPollsFn = createServerFn({ method: 'GET' })
  .handler(async () => {
    return await listPolls()
  })

export const Route = createFileRoute('/')({
  loader: async () => {
    return await getPollsFn()
  },
  component: HomeComponent,
})

function HomeComponent() {
  const polls = Route.useLoaderData()
  const navigate = useNavigate()

  const [question, setQuestion] = useState('')
  const [options, setOptions] = useState<string[]>(['', ''])
  const [error, setError] = useState<string | null>(null)
  const [loading, setLoading] = useState(false)

  const handleOptionChange = (index: number, value: string) => {
    const newOptions = [...options]
    newOptions[index] = value
    setOptions(newOptions)
  }

  const addOption = () => {
    setOptions([...options, ''])
  }

  const removeOption = (index: number) => {
    if (options.length <= 2) return
    const newOptions = options.filter((_, i) => i !== index)
    setOptions(newOptions)
  }

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault()
    setError(null)
    setLoading(true)

    try {
      const res = await fetch('/api/polls', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify({
          question,
          options: options.filter(opt => opt.trim() !== ''),
        }),
      })

      const data = await res.json()

      if (!res.ok) {
        setError(data.error || 'Failed to create poll')
        setLoading(false)
        return
      }

      // Redirect to the newly created poll page
      navigate({ to: '/poll/$id', params: { id: data.id } })
    } catch (err: any) {
      setError(err.message || 'An error occurred')
      setLoading(false)
    }
  }

  return (
    <div>
      <div className="card">
        <h2>Create a New Poll</h2>
        {error && <div className="error">{error}</div>}
        <form onSubmit={handleSubmit}>
          <div style={{ marginBottom: '1rem' }}>
            <label style={{ display: 'block', fontWeight: 'bold', marginBottom: '0.5rem' }}>
              Question:
            </label>
            <input
              type="text"
              value={question}
              onChange={(e) => setQuestion(e.target.value)}
              placeholder="What is your favorite programming language?"
              style={{
                width: '100%',
                padding: '0.5rem',
                borderRadius: '0.375rem',
                border: '1px solid #d1d5db',
                boxSizing: 'border-box'
              }}
              required
            />
          </div>

          <div style={{ marginBottom: '1rem' }}>
            <label style={{ display: 'block', fontWeight: 'bold', marginBottom: '0.5rem' }}>
              Options:
            </label>
            {options.map((option, index) => (
              <div key={index} style={{ display: 'flex', gap: '0.5rem', marginBottom: '0.5rem' }}>
                <input
                  type="text"
                  value={option}
                  onChange={(e) => handleOptionChange(index, e.target.value)}
                  placeholder={`Option ${index + 1}`}
                  style={{
                    flex: 1,
                    padding: '0.5rem',
                    borderRadius: '0.375rem',
                    border: '1px solid #d1d5db',
                    boxSizing: 'border-box'
                  }}
                  required={index < 2}
                />
                {options.length > 2 && (
                  <button
                    type="button"
                    onClick={() => removeOption(index)}
                    className="btn btn-secondary"
                    style={{ padding: '0.5rem' }}
                  >
                    Remove
                  </button>
                )}
              </div>
            ))}
            <button
              type="button"
              onClick={addOption}
              className="btn btn-secondary"
              style={{ marginTop: '0.5rem' }}
            >
              + Add Option
            </button>
          </div>

          <button type="submit" className="btn" disabled={loading}>
            {loading ? 'Creating...' : 'Create Poll'}
          </button>
        </form>
      </div>

      <div className="card">
        <h2>Active Polls</h2>
        {polls.length === 0 ? (
          <p style={{ color: '#6b7280' }}>No active polls yet. Create one above!</p>
        ) : (
          <ul style={{ listStyle: 'none', padding: 0, margin: 0 }}>
            {polls.map((poll) => (
              <li
                key={poll.id}
                style={{
                  padding: '1rem 0',
                  borderBottom: '1px solid #e5e7eb',
                  display: 'flex',
                  justifyContent: 'space-between',
                  alignItems: 'center'
                }}
              >
                <div>
                  <h3 style={{ margin: '0 0 0.25rem 0' }}>
                    <Link
                      to="/poll/$id"
                      params={{ id: poll.id }}
                      style={{ color: '#2563eb', textDecoration: 'none' }}
                    >
                      {poll.question}
                    </Link>
                  </h3>
                  <span style={{ fontSize: '0.875rem', color: '#6b7280' }}>
                    {poll.totalVotes} {poll.totalVotes === 1 ? 'vote' : 'votes'}
                  </span>
                </div>
                <Link
                  to="/poll/$id"
                  params={{ id: poll.id }}
                  className="btn btn-secondary"
                  style={{ textDecoration: 'none' }}
                >
                  View Poll
                </Link>
              </li>
            ))}
          </ul>
        )}
      </div>
    </div>
  )
}

import { createFileRoute } from '@tanstack/react-router'
import { createServerFn } from '@tanstack/react-start'
import { useState, useEffect } from 'react'
import { getPoll, Poll } from '../db'

const getPollFn = createServerFn({ method: 'GET' })
  .validator((id: string) => id)
  .handler(async ({ data: id }) => {
    return await getPoll(id)
  })

export const Route = createFileRoute('/poll/$id')({
  loader: async ({ params }) => {
    const poll = await getPollFn({ data: params.id })
    if (!poll) {
      throw new Error('Poll not found')
    }
    return poll
  },
  component: PollComponent,
  errorComponent: () => (
    <div className="card">
      <h2>Poll Not Found</h2>
      <p>The poll you are looking for does not exist or has been deleted.</p>
      <a href="/" className="btn">Go Back Home</a>
    </div>
  ),
})

function PollComponent() {
  const initialPoll = Route.useLoaderData()
  const [poll, setPoll] = useState<Poll>(initialPoll)
  const [voteError, setVoteError] = useState<string | null>(null)
  const [votingId, setVotingId] = useState<string | null>(null)

  // Poll for updates every 1 second to implement live results
  useEffect(() => {
    const interval = setInterval(async () => {
      try {
        const res = await fetch(`/api/polls/${poll.id}`)
        if (res.ok) {
          const data = await res.json()
          setPoll(data)
        }
      } catch (err) {
        console.error('Failed to fetch updated poll', err)
      }
    }, 1000)

    return () => clearInterval(interval)
  }, [poll.id])

  const handleVote = async (optionId: string) => {
    setVoteError(null)
    setVotingId(optionId)

    try {
      const res = await fetch(`/api/polls/${poll.id}/vote`, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify({ optionId }),
      })

      const data = await res.json()

      if (!res.ok) {
        setVoteError(data.error || 'Failed to cast vote')
        return
      }

      setPoll(data)
    } catch (err: any) {
      setVoteError(err.message || 'An error occurred while voting')
    } finally {
      setVotingId(null)
    }
  }

  return (
    <div className="card">
      <h2 style={{ marginBottom: '1.5rem' }}>{poll.question}</h2>

      {voteError && (
        <div data-testid="vote-error" className="error" style={{ marginBottom: '1.5rem' }}>
          {voteError}
        </div>
      )}

      <div style={{ display: 'flex', flexDirection: 'column', gap: '1rem', marginBottom: '2rem' }}>
        {poll.options.map((option) => {
          const percent = poll.totalVotes === 0 ? 0 : Math.round((option.votes / poll.totalVotes) * 100)

          return (
            <div
              key={option.id}
              style={{
                border: '1px solid #e5e7eb',
                borderRadius: '0.5rem',
                padding: '1rem',
                backgroundColor: '#f9fafb',
                position: 'relative',
                overflow: 'hidden'
              }}
            >
              {/* Progress bar background */}
              <div
                style={{
                  position: 'absolute',
                  top: 0,
                  left: 0,
                  bottom: 0,
                  width: `${percent}%`,
                  backgroundColor: '#dbeafe',
                  zIndex: 1,
                  transition: 'width 0.5s ease-out-in'
                }}
              />

              <div
                style={{
                  position: 'relative',
                  zIndex: 2,
                  display: 'flex',
                  justifyContent: 'space-between',
                  alignItems: 'center'
                }}
              >
                <div style={{ display: 'flex', alignItems: 'center', gap: '1rem', flex: 1 }}>
                  <button
                    data-testid={`vote-${option.id}`}
                    onClick={() => handleVote(option.id)}
                    disabled={votingId !== null}
                    className="btn"
                    style={{
                      padding: '0.375rem 0.75rem',
                      fontSize: '0.875rem'
                    }}
                  >
                    {votingId === option.id ? 'Voting...' : 'Vote'}
                  </button>
                  <span style={{ fontWeight: 500 }}>{option.text}</span>
                </div>

                <div style={{ display: 'flex', alignItems: 'center', gap: '1.5rem' }}>
                  <span
                    data-testid={`count-${option.id}`}
                    style={{ fontWeight: 'bold', minWidth: '3rem', textAlign: 'right' }}
                  >
                    {option.votes}
                  </span>
                  <span
                    data-testid={`percent-${option.id}`}
                    style={{
                      fontWeight: 'bold',
                      color: '#2563eb',
                      minWidth: '3.5rem',
                      textAlign: 'right'
                    }}
                  >
                    {percent}%
                  </span>
                </div>
              </div>
            </div>
          )
        })}
      </div>

      <div
        style={{
          borderTop: '1px solid #e5e7eb',
          paddingTop: '1rem',
          display: 'flex',
          justifyContent: 'space-between',
          alignItems: 'center',
          color: '#4b5563'
        }}
      >
        <span>
          Total Votes: <strong data-testid="total-votes">{poll.totalVotes}</strong>
        </span>
        <a href="/" style={{ color: '#2563eb', textDecoration: 'none', fontWeight: 500 }}>
          ← Back to All Polls
        </a>
      </div>
    </div>
  )
}

